// Build registry from active workflows
const workflows = $input.first().json.data || [];

// Filter active workflows starting with 'MCP -' (excluding this registry)
const mcpWorkflows = workflows.filter(w => 
  w.active && 
  w.name.startsWith('MCP -') && 
  w.name !== 'MCP - Registry'
);

// Extract webhook info from each workflow
const services = {};

for (const workflow of mcpWorkflows) {
  // Find webhook node
  const webhookNode = workflow.nodes?.find(n => 
    n.type === 'n8n-nodes-base.webhook'
  );

  if (webhookNode) {
    const webhookPath = webhookNode.parameters?.path || webhookNode.webhookId;
    const serviceName = workflow.name.replace('MCP - ', '').toLowerCase().replace(/[^a-z0-9]/g, '-');

    // Extract operations from node names or parameters
    const operationNodes = workflow.nodes?.filter(n => 
      n.type !== 'n8n-nodes-base.webhook' && 
      n.type !== 'n8n-nodes-base.respondToWebhook' &&
      n.type !== 'n8n-nodes-base.switch' &&
      n.type !== 'n8n-nodes-base.stickyNote'
    ) || [];

    // Group operations by resource
    const operations = {};
    for (const node of operationNodes) {
      const resource = node.parameters?.resource || 'default';
      const operation = node.parameters?.operation || node.name;
      if (!operations[resource]) {
        operations[resource] = [];
      }
      if (!operations[resource].includes(operation)) {
        operations[resource].push(operation);
      }
    }

    services[serviceName] = {
      name: workflow.name,
      workflow_id: workflow.id,
      webhook_url: `http://pi6.local:5678/webhook/${webhookPath}`,
      active: workflow.active,
      operations: operations
    };
  }
}

const registry = {
  version: "1.0",
  updated_at: new Date().toISOString(),
  n8n: {
    host: "pi6.local",
    port: 5678,
    protocol: "http"
  },
  total_services: Object.keys(services).length,
  services: services
};

return { json: registry };
